    for part in text.split(','):
        step = 1
        if '/' in part:
            part, step = part.split('/')
            step = int(step)
        if part == '*':
            a, b = lo, hi
        elif '-' in part:
            a, b = (int(x) for x in part.split('-'))
        else:
            a = b = int(part)
        for v in range(a, b + 1):
            if v % step == 0:
                out.add(v)
    return out

